CREATE TABLE IF NOT EXISTS products (
  id VARCHAR(64) PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  brand VARCHAR(100),
  category VARCHAR(100) NOT NULL,
  price NUMERIC(10,2) NOT NULL,
  original_price NUMERIC(10,2),
  discount_percentage INTEGER,
  currency VARCHAR(10) DEFAULT 'EGY',
  quantity INTEGER DEFAULT 10,
  availability VARCHAR(50) DEFAULT 'in_stock',
  rating NUMERIC(3,2),
  review_count INTEGER,
  source VARCHAR(50) DEFAULT 'amazon',
  source_product_id VARCHAR(100),
  source_url TEXT,
  source_website VARCHAR(50),
  video_url TEXT,
  is_new BOOLEAN DEFAULT false,
  is_sale BOOLEAN DEFAULT false,
  image_url TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS product_colors (
  id VARCHAR(64) PRIMARY KEY,
  product_id VARCHAR(64) REFERENCES products(id) ON DELETE CASCADE,
  name VARCHAR(50) NOT NULL,
  hex_code VARCHAR(10),
  image_url TEXT,
  sku TEXT,
  source_url TEXT,
  price NUMERIC
);

CREATE TABLE IF NOT EXISTS product_images (
  id VARCHAR(64) PRIMARY KEY,
  product_id VARCHAR(64) REFERENCES products(id) ON DELETE CASCADE,
  image_url TEXT NOT NULL,
  position INTEGER DEFAULT 0,
  color_id VARCHAR(64)
);

CREATE TABLE IF NOT EXISTS product_sizes (
  id VARCHAR(64) PRIMARY KEY,
  product_id VARCHAR(64) REFERENCES products(id) ON DELETE CASCADE,
  name VARCHAR(20) NOT NULL,
  available BOOLEAN DEFAULT true
);

CREATE TABLE IF NOT EXISTS product_skus (
  id VARCHAR(64) PRIMARY KEY,
  product_id VARCHAR(64) REFERENCES products(id) ON DELETE CASCADE,
  color_id VARCHAR(64),
  size_id VARCHAR(64),
  sku_code VARCHAR(100) UNIQUE NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS sku_inventory (
  sku_id VARCHAR(64) PRIMARY KEY REFERENCES product_skus(id) ON DELETE CASCADE,
  on_hand_quantity INTEGER NOT NULL DEFAULT 10,
  reserved_quantity INTEGER NOT NULL DEFAULT 0,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS recommendation_config (
  key VARCHAR(64) PRIMARY KEY,
  value JSONB NOT NULL,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


